function readFixedLegacyCurrentEntryStoreIfPresentV1(): Readonly<{ directory: string; device: bigint }> | null {
  const repository = directorySnapshot(fixedRepositoryRoot(), "Setfarm repository");
  const workspacePath = CODE_OWNED_WORKSPACE_ROOT_V1;
  const workspace = directorySnapshot(workspacePath, "Setfarm workspace", repository.device);
  let directory = workspacePath;
  let parentDirectory = workspacePath;
  let parentSnapshot = workspace;
  for (const segment of LEGACY_CURRENT_ENTRY_STORE_SEGMENTS_V1) {
    directory = path.join(directory, segment);
    try {
      lstatSync(directory, { bigint: true });
    } catch (error) {
      if (!isEnoent(error)) throw error;
      assertDirectory(parentDirectory, parentSnapshot, `parent of absent fixed legacy current-entry store ${segment}`);
      try {
        lstatSync(directory, { bigint: true });
      } catch (reobservedError) {
        if (!isEnoent(reobservedError)) throw reobservedError;
        assertDirectory(parentDirectory, parentSnapshot, `parent of absent fixed legacy current-entry store ${segment}`);
        return null;
      }
      currentEntryFail(`absent fixed legacy current-entry store ${segment} appeared while observed`);
    }
    const observed = directorySnapshot(directory, `fixed legacy current-entry store ${segment}`, workspace.device);
    if (observed.identity.mode !== 0o700) currentEntryFail(`fixed legacy current-entry store ${segment} has wrong mode`);
    assertDirectory(parentDirectory, parentSnapshot, `parent of fixed legacy current-entry store ${segment}`);
    parentDirectory = directory;
    parentSnapshot = observed;
  }
  return Object.freeze({ directory, device: workspace.device });
}

function readFixedLegacyCurrentEntryRecordSnapshotIfPresentV1(target: string, label: string): FileSnapshot | null {
  const repository = directorySnapshot(fixedRepositoryRoot(), "Setfarm repository");
  const workspacePath = CODE_OWNED_WORKSPACE_ROOT_V1;
  const workspace = directorySnapshot(workspacePath, "Setfarm workspace", repository.device);
  const resolved = path.resolve(target);
  const relative = path.relative(workspacePath, resolved);
  if (
    !relative.startsWith("data/internal-production-baseline/")
    || relative === ".."
    || relative.startsWith(`..${path.sep}`)
    || path.isAbsolute(relative)
  ) currentEntryFail(`${label} escaped the fixed legacy workspace`);
  const segments = relative.split(path.sep);
  const basename = segments.pop();
  if (!basename || segments.some((segment) => !segment || segment === "." || segment === "..")) {
    currentEntryFail(`${label} locator is invalid`);
  }
  let directory = workspacePath;
  let directoryState = workspace;
  for (const segment of segments) {
    const child = path.join(directory, segment);
    try {
      lstatSync(child, { bigint: true });
    } catch (error) {
      if (!isEnoent(error)) throw error;
      assertDirectory(directory, directoryState, `parent of absent ${label} ${segment}`);
      try {
        lstatSync(child, { bigint: true });
      } catch (reobservedError) {
        if (!isEnoent(reobservedError)) throw reobservedError;
        assertDirectory(directory, directoryState, `parent of absent ${label} ${segment}`);
        return null;
      }
      currentEntryFail(`absent ${label} ${segment} appeared while observed`);
    }
    const observed = directorySnapshot(child, `${label} ${segment}`, workspace.device);
    if (observed.identity.mode !== 0o700) currentEntryFail(`${label} ${segment} has wrong mode`);
    assertDirectory(directory, directoryState, `parent of ${label} ${segment}`);
    directory = child;
    directoryState = observed;
  }
  const record = path.join(directory, basename);
  const guard = authenticateTask12ReceiptDirectoryChainV1(directory);
  try {
    guard.assertStable();
    try {
      lstatSync(record, { bigint: true });
    } catch (error) {
      if (!isEnoent(error)) throw error;
      guard.assertStable();
      try {
        lstatSync(record, { bigint: true });
      } catch (reobservedError) {
        if (!isEnoent(reobservedError)) throw reobservedError;
        guard.assertStable();
        return null;
      }
      currentEntryFail(`absent ${label} record appeared while observed`);
    }
    const observed = readStableRegular(record, CURRENT_ENTRY_MAX_BYTES, workspace.device);
    if (observed.mode !== 0o600) currentEntryFail(`${label} record has wrong mode`);
    guard.assertStable();
    return Object.freeze({ locator: record, observed });
  } finally {
    guard.close();
  }
}

function parsePreselectionCurrentEntryOperationV1(bytes: Buffer): Readonly<{
  operationRef: string;
  operationHash: Sha256V1;
}> {
  const body = strictCanonicalRecord(bytes, "fixed legacy current-entry operation");
  if (!hasExactKeys(body, ["schema", "purpose", "controllerSource", "productBuildAuthorityV2DeliveryEvidence", "productBuildAuthorityV2Observation", "authorityV3Migration31Audit", "pendingBootstrapHandoffMigration", "operationRef", "operationHash"])) {
    currentEntryFail("fixed legacy current-entry operation fields are invalid");
  }
  if (body.schema !== "setfarm.internal-production-current-entry-operation.v1" || body.purpose !== "task6a-internal-production-current-entry-v1") {
    currentEntryFail("fixed legacy current-entry operation discriminator is invalid");
  }
  const projection = { ...body };
  delete projection.operationRef;
  delete projection.operationHash;
  const operationHash = requireSha256(body.operationHash, "fixed legacy current-entry operation hash");
  const operationRef = body.operationRef;
  if (
    hashCanonicalJson(projection) !== operationHash
    || typeof operationRef !== "string"
    || operationRef !== `setfarm://internal-production/current-entry-operation/sha256/${operationHash}`
  ) currentEntryFail("fixed legacy current-entry operation pair/hash is invalid");
  requireSource(body.controllerSource);
  requirePair(body.authorityV3Migration31Audit, "authorityV3Migration31AuditRef", "authorityV3Migration31AuditHash", "setfarm://internal-production/authority-v3-migration31-audit/sha256/");
  requirePair(body.pendingBootstrapHandoffMigration, "pendingBootstrapHandoffMigrationRef", "pendingBootstrapHandoffMigrationHash", "setfarm://internal-production/pending-bootstrap-handoff-migration/sha256/");
  if (
    !isPlainRecord(body.productBuildAuthorityV2Observation)
    || !hasExactKeys(body.productBuildAuthorityV2Observation, ["schema", "observationTransport", "response"])
    || body.productBuildAuthorityV2Observation.schema !== "setfarm.product-build-authority-v2-delivery-evidence-observation.v1"
    || body.productBuildAuthorityV2Observation.observationTransport !== "source-cli"
  ) currentEntryFail("fixed legacy current-entry PBA observation is invalid");
  const observedPbaPair = pbaPair(body.productBuildAuthorityV2Observation as ProductBuildAuthorityObservationV1);
  const storedPbaPair = requirePair(body.productBuildAuthorityV2DeliveryEvidence, "deliveryEvidenceRef", "deliveryEvidenceHash", "mission-control://internal-production/product-build-authority-v2-delivery-evidence/sha256/");
  if (
    storedPbaPair.deliveryEvidenceRef !== observedPbaPair.deliveryEvidenceRef
    || storedPbaPair.deliveryEvidenceHash !== observedPbaPair.deliveryEvidenceHash
  ) currentEntryFail("fixed legacy current-entry PBA pair is crossed");
  return Object.freeze({ operationRef, operationHash });
}

const CURRENT_ENTRY_STORE_ZERO_EFFECT_PROOF_PREFIX_V1 = "setfarm://internal-production/current-entry-store-zero-effect-proof/sha256/";
const CURRENT_ENTRY_STORE_QUARANTINE_DISPOSITION_PREFIX_V1 = "setfarm://internal-production/current-entry-store-quarantine-disposition/sha256/";
const CURRENT_ENTRY_STORE_SUCCESSOR_EDGE_PREFIX_V1 = "setfarm://internal-production/current-entry-store-successor-edge/sha256/";
const CURRENT_ENTRY_STORE_SUCCESSOR_ACTIVATION_SEAL_PREFIX_V1 = "setfarm://internal-production/current-entry-store-successor-activation-seal/sha256/";
const CURRENT_ENTRY_STORE_SUCCESSOR_ACTIVATION_COMMIT_PREFIX_V1 = "setfarm://internal-production/current-entry-store-successor-activation-commit/sha256/";

const EXACT_POISON_PREDECESSOR_FILE_IDENTITIES_V1 = Object.freeze([
  Object.freeze({ locator: "current-entry-operation.json", uidDecimal: "501", deviceDecimal: "16777230", inodeDecimal: "133141401" }),
  Object.freeze({ locator: "records/authority-v3-migration31-audits/sha256/31/319576e4632f52b03f9dd1c5a8ec893b8ffe4091524deaac692792a389ddf76d.json", uidDecimal: "501", deviceDecimal: "16777230", inodeDecimal: "133141143" }),
  Object.freeze({ locator: "records/authority-v3-migration31-audits/sha256/e2/e2165d663f766b2506245a1018d5195c919e8deeb7eeff82b0f35a5e61cc3025.json", uidDecimal: "501", deviceDecimal: "16777230", inodeDecimal: "133136356" }),
  Object.freeze({ locator: "records/pending-bootstrap-handoff-migrations/sha256/6e/6e3c6e68f5888b1092a89f6b48a990ff83a88ebdfd7be9c8c51f721a29f09741.json", uidDecimal: "501", deviceDecimal: "16777230", inodeDecimal: "133141205" }),
  Object.freeze({ locator: "records/pending-bootstrap-handoff-migrations/sha256/ce/ce21b1c0b332b4f98bbb560a947c29fb80e0360046d2c34829d6c4e43c32b015.json", uidDecimal: "501", deviceDecimal: "16777230", inodeDecimal: "133136424" }),
] as const);

const EXACT_POISON_UNAVAILABLE_SYNTHETIC_GIT_OBJECTS_V1 = Object.freeze([
  Object.freeze({ repository: "setfarm", objectSha: "4fc67f20df0e935c703c4658a29dbbaa9aa0a956", objectType: "commit", state: "absent", networkAccess: "forbidden" }),
  Object.freeze({ repository: "mission-control", objectSha: "4ec5fc99a076453a87381c0c75e508d25dd8882d", objectType: "commit", state: "absent", networkAccess: "forbidden" }),
] as const);

function exactPoisonOperationPairV1(): ExactPoisonOperationPairV1 {
  return Object.freeze({
    operationRef: EXACT_POISON_OPERATION_REF_V1,
    operationHash: EXACT_POISON_OPERATION_HASH_V1,
  });
}

function requireCurrentEntryStorePairV1(
  value: unknown,
  refKey: string,
  hashKey: string,
  prefix: string,
): CurrentEntryStoreRecordPairV1 {
  const pair = requirePair(value, refKey, hashKey, prefix);
  return Object.freeze({ ref: pair[refKey]!, hash: pair[hashKey]! as Sha256V1 });
}

function requireCurrentEntryStorePairFromRecordV1(
  value: unknown,
  refKey: string,
  hashKey: string,
  prefix: string,
): CurrentEntryStoreRecordPairV1 {
  if (!isPlainRecord(value)) currentEntryFail(`${refKey} containing record is invalid`);
  return requireCurrentEntryStorePairV1({ [refKey]: value[refKey], [hashKey]: value[hashKey] }, refKey, hashKey, prefix);
}

function assertCurrentEntryStorePairEqualV1(
  observed: CurrentEntryStoreRecordPairV1,
  expected: CurrentEntryStoreRecordPairV1,
  label: string,
): void {
  if (observed.ref !== expected.ref || observed.hash !== expected.hash) currentEntryFail(`${label} pair is crossed`);
}

function requireExactPoisonPredecessorV1(value: unknown, label: string): ExactPoisonOperationPairV1 {
  const pair = requireCurrentEntryStorePairV1(
    value,
    "operationRef",
    "operationHash",
    "setfarm://internal-production/current-entry-operation/sha256/",
  );
  if (pair.ref !== EXACT_POISON_OPERATION_REF_V1 || pair.hash !== EXACT_POISON_OPERATION_HASH_V1) {
    currentEntryFail(`${label} predecessor is crossed`);
  }
  return exactPoisonOperationPairV1();
}

function parseCurrentEntryStoreHashedWrapperV1(
  bytes: Buffer,
  label: string,
  coreKeys: readonly string[],
  refKey: string,
  hashKey: string,
  prefix: string,
  expectedHash?: Sha256V1,
): Readonly<{ value: Record<string, unknown>; core: Record<string, unknown>; pair: CurrentEntryStoreRecordPairV1 }> {
  const value = strictCanonicalRecord(bytes, label);
  if (!hasExactKeys(value, [...coreKeys, refKey, hashKey])) currentEntryFail(`${label} fields are invalid`);
  const core = { ...value };
  delete core[refKey];
  delete core[hashKey];
  const pair = requireCurrentEntryStorePairV1(
    { [refKey]: value[refKey], [hashKey]: value[hashKey] },
    refKey,
    hashKey,
    prefix,
  );
  if (hashCanonicalJson(core) !== pair.hash || (expectedHash !== undefined && pair.hash !== expectedHash)) {
    currentEntryFail(`${label} hash is crossed`);
  }
  return Object.freeze({ value, core, pair });
}

