async function observeExactPoisonPostVisiblePreStatusRawFenceNoWriteV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
  originals: ExactPoisonRecoveryInventoryEvidenceV1,
): Promise<ExactPoisonPostVisiblePreStatusRawFenceV1> {
  context.assertStable();
  originals.assertStableOriginals();
  const syntheticGitAbsence = observeExactPoisonSyntheticGitObjectAbsenceV1();
  const sourceA = requireSource(observeCurrentInternalProductionCleanSetfarmSourceBuildV1());
  const pbaA = await observeCurrentPba();
  const prerequisitesA = requireExactPoisonRecoveryPrerequisitesV1(await observeExactPoisonRecoveryCurrentPrerequisitesNoWriteV1());
  const phaseA = requireExactZeroCountsV1(await observePhaseClosedZeroV1(sourceA), EXACT_POISON_PHASE_ZERO_KEYS_V1, "pre-status phase-a");
  const serviceA = await observeInternalProductionServiceCensusV1();
  const physicalA = observePhysicalInventoryV1(serviceA, 0);
  const database = requireExactZeroCountsV1(await observeLegacyDatabaseCensusV1(), [
    "activeRunCount", "openClaimCount", "executionAttemptCount", "activeRuntimeSessionCount", "activeCompletionOwnerCount",
    "unsettledMandatoryEffectCount", "artifactReservationCount", "publicationBatchCount", "artifactPublicationCount",
    "terminationOwnerCount", "findingOwnerCount", "recoveryOwnerCount", "operationalDeliveryCount",
  ], "pre-status database");
  const downstreamA = await observeExactPoisonPostVisiblePreStatusDownstreamNoWriteV1(database, phaseA, physicalA);
  const serviceB = await observeInternalProductionServiceCensusV1();
  const physicalB = observePhysicalInventoryV1(serviceB, 0);
  const phaseB = requireExactZeroCountsV1(await observePhaseClosedZeroV1(sourceA), Object.keys(phaseA), "pre-status phase-b");
  const sourceB = requireSource(observeCurrentInternalProductionCleanSetfarmSourceBuildV1());
  const pbaB = await observeCurrentPba();
  const prerequisitesB = requireExactPoisonRecoveryPrerequisitesV1(await observeExactPoisonRecoveryCurrentPrerequisitesNoWriteV1());
  const downstreamB = await observeExactPoisonPostVisiblePreStatusDownstreamNoWriteV1(database, phaseB, physicalB);
  const expectedOperation = context.successorOperation;
  if (
    canonicalComparable(sourceA) !== canonicalComparable(sourceB)
    || canonicalComparable(pbaA) !== canonicalComparable(pbaB)
    || canonicalComparable(prerequisitesA) !== canonicalComparable(prerequisitesB)
    || canonicalComparable(serviceA) !== canonicalComparable(serviceB)
    || canonicalComparable(physicalA) !== canonicalComparable(physicalB)
    || canonicalComparable(phaseA) !== canonicalComparable(phaseB)
    || canonicalComparable(downstreamA) !== canonicalComparable(downstreamB)
  ) currentEntryFail("post-visible pre-status raw A/B observation changed");
  if (
    canonicalComparable(sourceA) !== canonicalComparable(expectedOperation.controllerSource)
    || canonicalComparable(pbaA) !== canonicalComparable(expectedOperation.productBuildAuthorityV2Observation)
    || canonicalComparable(pbaPair(pbaA)) !== canonicalComparable(expectedOperation.productBuildAuthorityV2DeliveryEvidence)
    || canonicalComparable(prerequisitesA.authorityV3Migration31Audit.pair) !== canonicalComparable(expectedOperation.authorityV3Migration31Audit)
    || canonicalComparable(prerequisitesA.pendingBootstrapHandoffMigration.pair) !== canonicalComparable(expectedOperation.pendingBootstrapHandoffMigration)
  ) currentEntryFail("post-visible pre-status raw authority is crossed with the pinned successor operation");
  originals.assertStableOriginals();
  context.assertStable();
  const completeZeroEffectBracket: CompleteZeroEffectBracketHashInputV1 = recursivelyFreeze([
    { observation: "controller-source-a", value: sourceA },
    { observation: "product-build-authority-a", value: pbaA },
    { observation: "authority-v3-migration31-audit-a", value: prerequisitesA.authorityV3Migration31Audit.value },
    { observation: "pending-bootstrap-handoff-migration-a", value: prerequisitesA.pendingBootstrapHandoffMigration.value },
    { observation: "service-a", value: serviceA },
    { observation: "physical-a", value: physicalA },
    { observation: "database-owner-migration-manifest", value: database },
    { observation: "downstream-absence", value: downstreamA },
    { observation: "service-b", value: serviceB },
    { observation: "physical-b", value: physicalB },
    { observation: "controller-source-b", value: sourceB },
    { observation: "product-build-authority-b", value: pbaB },
    { observation: "authority-v3-migration31-audit-b", value: prerequisitesB.authorityV3Migration31Audit.value },
    { observation: "pending-bootstrap-handoff-migration-b", value: prerequisitesB.pendingBootstrapHandoffMigration.value },
  ]);
  return Object.freeze({
    completeZeroEffectBracket,
    completeZeroEffectBracketHash: hashCanonicalJson(completeZeroEffectBracket),
    syntheticGitAbsence,
    serviceCensus: serviceA,
  });
}

async function observeExactPoisonQuarantineAdmissionV1(
  operation: FileSnapshot,
  heldWriter: ExactPoisonRecoveryWriterV1,
  expectedPublished: readonly ExactPoisonRecoveryCandidateV1[] = Object.freeze([]),
): Promise<ExactPoisonQuarantineAdmissionV1> {
  return observeExactPoisonQuarantineAdmissionCoreV1(operation, heldWriter, expectedPublished);
}

type ExactPoisonPreStatusDirectoryObservationV1 = Readonly<
  | { state: "absent"; target: string }
  | { state: "directory"; target: string; identity: Task12ReceiptPhysicalIdentityObservationV1; members: readonly string[] }
>;

function exactPoisonPreStatusPathStateV1(
  target: string,
  successorRoot: string,
  successorRootIdentity: BigIntStats,
): ExactPoisonPreStatusDirectoryObservationV1 {
  try {
    const before = lstatSync(target, { bigint: true });
    if (
      !before.isDirectory()
      || before.isSymbolicLink()
      || (before.mode & 0o7777n) !== 0o700n
      || before.dev !== successorRootIdentity.dev
      || before.uid !== successorRootIdentity.uid
      || realpathSync(target) !== path.join(realpathSync(successorRoot), path.relative(successorRoot, target))
    ) currentEntryFail("post-visible P0 directory mode, device, owner, or canonical path is invalid");
    const members = Object.freeze(readdirSync(target).sort(compareBytes));
    const after = lstatSync(target, { bigint: true });
    if (!sameRegularMetadata(before, after)) currentEntryFail("post-visible P0 directory changed during observation");
    return Object.freeze({ state: "directory" as const, target, identity: observeTask12ReceiptPhysicalIdentityV1(after), members });
  } catch (error) {
    if (isEnoent(error)) return Object.freeze({ state: "absent" as const, target });
    throw error;
  }
}

function exactPoisonPreStatusOperationDirectoryMembersV1(
  publicationSet: Task12PreparedCurrentEntryPublicationSetV1,
  observed: ExactPoisonPreStatusDirectoryObservationV1,
): readonly string[] {
  const operationDirectory = publicationSet.operationDirectoryPrefix[3];
  if (observed.state !== "directory" || observed.target !== operationDirectory) currentEntryFail("post-visible operation directory observation is absent or crossed");
  const controllerFixed = `.${path.basename(publicationSet.controllerLockTarget)}.writer.lock`;
  const controllerTempPrefix = `${controllerFixed}.tmp-`;
  const operationCandidates = publicationSet.candidates.filter((candidate) => path.dirname(candidate.target) === operationDirectory);
  const permittedFamily = (member: string): boolean => operationCandidates.some((candidate) => {
    const basename = path.basename(candidate.target);
    return member === basename
      || member.startsWith(`${basename}.tmp-`)
      || member === `.${basename}.writer.lock`
      || member.startsWith(`.${basename}.writer.lock.tmp-`);
  });
  const members = observed.members;
  for (const member of members) {
    if (member === controllerFixed || member.startsWith(controllerTempPrefix) || permittedFamily(member)) continue;
    currentEntryFail("post-visible P0 operation-directory member is invalid");
  }
  return Object.freeze(members);
}

type ExactPoisonPreStatusRecordPrefixObservationsV1 = Readonly<{
  observations: readonly ExactPoisonPreStatusDirectoryObservationV1[];
  candidateDepths: readonly [number, number];
  candidateParents: readonly [ExactPoisonPreStatusDirectoryObservationV1, ExactPoisonPreStatusDirectoryObservationV1];
}>;

function observeExactPoisonPreStatusRecordPrefixesV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
  publicationSet: Task12PreparedCurrentEntryPublicationSetV1,
  successorRootIdentity: BigIntStats,
): ExactPoisonPreStatusRecordPrefixObservationsV1 {
  const recordsRoot = path.join(context.successorRoot, "records");
  const baselineTargets = [context.successorAuthorityV31.target, context.successorPending.target] as const;
  const candidateTargets = [publicationSet.candidates[0].target, publicationSet.candidates[2].target] as const;
  const chainFor = (target: string): readonly [string, string, string] => Object.freeze([
    path.dirname(path.dirname(path.dirname(target))),
    path.dirname(path.dirname(target)),
    path.dirname(target),
  ] as [string, string, string]);
  const baselineChains = baselineTargets.map(chainFor);
  const candidateChains = candidateTargets.map(chainFor);
  const observations: ExactPoisonPreStatusDirectoryObservationV1[] = [];
  const observeChain = (
    chain: readonly [string, string, string],
    requireComplete: boolean,
    exactLeafMember: string | null,
  ): Readonly<{ depth: number; entries: readonly ExactPoisonPreStatusDirectoryObservationV1[] }> => {
    const entries = chain.map((target) => exactPoisonPreStatusPathStateV1(target, context.successorRoot, successorRootIdentity));
    observations.push(...entries);
    let depth = 0;
    for (const [index, entry] of entries.entries()) {
      if (entry.state === "absent") {
        if (entries.slice(index + 1).some((later) => later.state !== "absent")) currentEntryFail("post-visible prepared record directory prefix has a gap");
        break;
      }
      depth = index + 1;
      const expectedMembers = index < entries.length - 1
        ? (entries[index + 1]!.state === "directory" ? [path.basename(chain[index + 1]!)] : [])
        : (exactLeafMember === null ? null : [exactLeafMember]);
      if (expectedMembers !== null && canonicalComparable(entry.members) !== canonicalComparable(expectedMembers)) {
        currentEntryFail("post-visible prepared record directory child set is not exact");
      }
    }
    if (requireComplete && depth !== chain.length) currentEntryFail("post-visible successor prerequisite directory prefix is incomplete");
    return Object.freeze({ depth, entries: Object.freeze(entries) });
  };
  const baseline = baselineChains.map((chain, index) => observeChain(chain, true, path.basename(baselineTargets[index]!)));
  const candidates = candidateChains.map((chain) => observeChain(chain, false, null));
  const recordsObservation = exactPoisonPreStatusPathStateV1(recordsRoot, context.successorRoot, successorRootIdentity);
  observations.unshift(recordsObservation);
  if (recordsObservation.state !== "directory") currentEntryFail("post-visible successor records root is absent");
  const expectedRecordKinds = new Set(baselineChains.map((chain) => path.basename(chain[0])));
  for (const [index, candidate] of candidates.entries()) {
    if (candidate.depth > 0) expectedRecordKinds.add(path.basename(candidateChains[index]![0]));
  }
  if (canonicalComparable(recordsObservation.members) !== canonicalComparable([...expectedRecordKinds].sort(compareBytes))) {
    currentEntryFail("post-visible successor records root child set is not exact");
  }
  void baseline;
  return Object.freeze({
    observations: Object.freeze(observations),
    candidateDepths: Object.freeze([candidates[0]!.depth, candidates[1]!.depth] as [number, number]),
    candidateParents: Object.freeze([candidates[0]!.entries[2]!, candidates[1]!.entries[2]!] as [ExactPoisonPreStatusDirectoryObservationV1, ExactPoisonPreStatusDirectoryObservationV1]),
  });
}

async function observeExactPoisonPostVisiblePreStatusPassNoWriteV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
): Promise<ExactPoisonPostVisiblePreStatusPassV1> {
  const phaseTopologyMembers = Object.freeze([
    "pre-mutation-content-publication",
    "pre-mutation-content-final",
    "00-pair-publication",
    "00-pair-final",
    "operation-prepared-status-publication",
    "operation-prepared-status-final",
    "01-current-status-publication-before-one-link",
  ]);
  const progressTopology = Object.freeze({ phase: "P5", finalStates: Object.freeze(["F2u", "F3", "F4"]), state: "progress" });
  context.assertStable();
  const originals = openExactPoisonRecoveryPostVisibleOriginalsV1(context);
  try {
    const rawFence = await observeExactPoisonPostVisiblePreStatusRawFenceNoWriteV1(context, originals.evidence);
    const publicationSet = await buildTask12PreparedCurrentEntryPublicationSetV1(
      createPinnedSuccessorTask12PreparedCurrentEntryPublicationAuthorityV1(context),
      rawFence.serviceCensus,
    );
    if (canonicalComparable(publicationSet.serviceCensus) !== canonicalComparable(rawFence.serviceCensus)) currentEntryFail("post-visible prepared builder census is crossed");
    originals.evidence.assertStableOriginals();
    context.assertStable();

    const successorRootIdentity = context.successorRootParent.identity;
    const recordPrefixes = observeExactPoisonPreStatusRecordPrefixesV1(context, publicationSet, successorRootIdentity);
    const prefixObservations: ExactPoisonPreStatusDirectoryObservationV1[] = [];
    let prefixDepth = 0;
    for (const [index, target] of publicationSet.operationDirectoryPrefix.entries()) {
      const observed = exactPoisonPreStatusPathStateV1(target, context.successorRoot, successorRootIdentity);
      prefixObservations.push(observed);
      if (observed.state === "absent") {
        for (const later of publicationSet.operationDirectoryPrefix.slice(index + 1)) {
          const laterObserved = exactPoisonPreStatusPathStateV1(later, context.successorRoot, successorRootIdentity);
          prefixObservations.push(laterObserved);
          if (laterObserved.state !== "absent") currentEntryFail("post-visible P0 directory prefix has a gap");
        }
        for (let parentIndex = 0; parentIndex < index; parentIndex += 1) {
          const parent = prefixObservations[parentIndex]!;
          if (parent.state !== "directory") currentEntryFail("post-visible P0 directory prefix is crossed");
          const expectedMembers = parentIndex + 1 < index ? [path.basename(publicationSet.operationDirectoryPrefix[parentIndex + 1]!)] : [];
          if (canonicalComparable(parent.members) !== canonicalComparable(expectedMembers)) currentEntryFail("post-visible P0 directory child set is not exact");
        }
        const publicationPolicy = Object.freeze([
          ...publicationSet.candidates.map((candidate) => Object.freeze({ target: candidate.target, allowFinal: true, allowPublicationTemporaries: true, allowWriterFamily: true })),
          Object.freeze({ target: publicationSet.controllerLockTarget, allowFinal: false, allowPublicationTemporaries: false, allowWriterFamily: true }),
        ]);
        const publicationStates = publicationSet.candidates.map((candidate) => observeTask12ReceiptPublicationNoWriteV1(candidate.target, candidate.bytes, publicationPolicy));
        if (publicationStates.some((entry) => entry.state !== "F0" || entry.members.length !== 0)) currentEntryFail("post-visible P0 has a later publication member");
        if (recordPrefixes.candidateDepths.some((depth) => depth !== 0)) currentEntryFail("post-visible P0 has a prepared record directory prefix");
        return Object.freeze({ stage: "P0", state: "pre-status", publicationSet, rawFence, topology: Object.freeze([prefixDepth, phaseTopologyMembers, prefixObservations, recordPrefixes.observations, publicationStates]) });
      }
      prefixDepth = index + 1;
    }
    for (let index = 0; index < publicationSet.operationDirectoryPrefix.length - 1; index += 1) {
      const observed = prefixObservations[index]!;
      if (observed.state !== "directory" || canonicalComparable(observed.members) !== canonicalComparable([path.basename(publicationSet.operationDirectoryPrefix[index + 1]!)])) {
        currentEntryFail("post-visible P0 directory child set is not exact");
      }
    }
    const operationMembers = exactPoisonPreStatusOperationDirectoryMembersV1(publicationSet, prefixObservations.at(-1)!);
    const controllerWriter = observeTask12ReceiptLocatorWriterNoWriteV1(publicationSet.controllerLockTarget);
    const publicationPolicy = Object.freeze([
      ...publicationSet.candidates.map((candidate) => Object.freeze({ target: candidate.target, allowFinal: true, allowPublicationTemporaries: true, allowWriterFamily: true })),
      Object.freeze({ target: publicationSet.controllerLockTarget, allowFinal: false, allowPublicationTemporaries: false, allowWriterFamily: true }),
    ]);
    const publicationStates = publicationSet.candidates.map((candidate) => observeTask12ReceiptPublicationNoWriteV1(candidate.target, candidate.bytes, publicationPolicy));
    const candidateWriters = publicationSet.candidates.map((candidate) => {
      try {
        const parent = lstatSync(path.dirname(candidate.target), { bigint: true });
        if (!parent.isDirectory() || parent.isSymbolicLink()) currentEntryFail("post-visible prepared writer parent is invalid");
        return observeTask12ReceiptLocatorWriterNoWriteV1(candidate.target);
      } catch (error) { if (isEnoent(error)) return null; throw error; }
    });
    const assertStageTopology = (currentIndex: number | null): void => {
      const expectedOperationMembers = new Set(controllerWriter.members.map((member) => path.basename(member.target)));
      for (const index of [1, 3] as const) {
        const candidate = publicationSet.candidates[index]!;
        const observed = publicationStates[index]!;
        const basename = path.basename(candidate.target);
        if (["F2", "F2u", "F3", "F4"].includes(observed.state)) expectedOperationMembers.add(basename);
        for (const temporary of observed.temporaryTargets) expectedOperationMembers.add(path.basename(temporary));
        const writerObservation = candidateWriters[index];
        if (writerObservation !== null && writerObservation.members.length > 0) {
          if (currentIndex !== index) currentEntryFail("post-visible prepared noncurrent writer family is present");
          for (const member of writerObservation.members) expectedOperationMembers.add(path.basename(member.target));
        }
      }
      for (const [index, writerObservation] of candidateWriters.entries()) {
        if (writerObservation !== null && writerObservation.members.length > 0 && currentIndex !== index) currentEntryFail("post-visible prepared earlier or later writer family is present");
      }
      if (canonicalComparable([...expectedOperationMembers].sort(compareBytes)) !== canonicalComparable([...operationMembers].sort(compareBytes))) {
        currentEntryFail("post-visible prepared operation-directory stage topology is crossed");
      }
    };
    const p2Parent = recordPrefixes.candidateParents[0];
    const p2PrefixDepth = recordPrefixes.candidateDepths[0];
    const p4PrefixDepth = recordPrefixes.candidateDepths[1];
    if (p4PrefixDepth > 0 && (p2PrefixDepth !== 3 || !["F2u", "F3", "F4"].includes(publicationStates[0]!.state) || !["F2u", "F3", "F4"].includes(publicationStates[1]!.state))) {
      currentEntryFail("post-visible P4 record directory prefix is out of order");
    }
    if (p2PrefixDepth === 0) {
      if (publicationStates.slice(1).some((entry) => entry.state !== "F0")) currentEntryFail("post-visible prepared publication order is crossed");
      const stage = controllerWriter.members.length === 0 ? "P0" as const : "P1" as const;
      assertStageTopology(null);
      return Object.freeze({ stage, state: "pre-status", publicationSet, rawFence, topology: Object.freeze([prefixDepth, phaseTopologyMembers, prefixObservations, recordPrefixes.observations, p2Parent, operationMembers, controllerWriter, candidateWriters, publicationStates]) });
    }
    if (p2PrefixDepth < 3) {
      if (publicationStates.some((entry) => entry.state !== "F0") || candidateWriters.some((entry) => entry !== null && entry.members.length > 0)) currentEntryFail("post-visible P2 partial directory prefix has publication evidence");
      assertStageTopology(0);
      return Object.freeze({ stage: "P2", state: "pre-status", publicationSet, rawFence, topology: Object.freeze([prefixDepth, phaseTopologyMembers, prefixObservations, recordPrefixes.observations, p2Parent, operationMembers, controllerWriter, candidateWriters, publicationStates]) });
    }
    const p2Writer = candidateWriters[0]!;
    if (p2Writer === null) currentEntryFail("post-visible P2 writer parent observation is absent");
    if (controllerWriter.members.length > 0 && publicationStates[0]!.state === "F0" && p2Writer.members.length === 0) {
      if (publicationStates.slice(1).some((entry) => entry.state !== "F0")) currentEntryFail("post-visible prepared publication order is crossed");
      assertStageTopology(null);
      return Object.freeze({ stage: "P1", state: "pre-status", publicationSet, rawFence, topology: Object.freeze([prefixDepth, phaseTopologyMembers, prefixObservations, recordPrefixes.observations, p2Parent, operationMembers, controllerWriter, candidateWriters, publicationStates]) });
    }
    const finalStates = new Set<Task12ReceiptPublicationNoWriteObservationV1["state"]>(["F2u", "F3", "F4"]);
    let stage: ExactPoisonPostVisiblePreStatusPassV1["stage"] = "P1";
    for (let index = 0; index < publicationStates.length; index += 1) {
      const observed = publicationStates[index]!;
      if (finalStates.has(observed.state)) {
        stage = (["P3", "P4", "P5", "P5"] as const)[index]!;
        continue;
      }
      for (const later of publicationStates.slice(index + 1)) {
        if (later.state !== "F0") currentEntryFail("post-visible prepared publication order is crossed");
      }
      if (observed.state === "F-1") {
        if (observed.temporaryTarget === null) currentEntryFail("post-visible prepared temporary target is missing");
        const temporary = observed.members.find((member) => member.target === observed.temporaryTarget);
        if (temporary === undefined) currentEntryFail("post-visible prepared temporary observation is missing");
        const classification = publicationSet.candidates[index]!.classifyTemporaryBytes(temporary.bytes);
        if (classification === "canonical-unequal") currentEntryFail("post-visible prepared canonical-unequal temporary is terminal");
        if (classification !== "incomplete-noncanonical") currentEntryFail("post-visible prepared temporary classification is crossed");
      }
      stage = (["P2", "P3", "P4", "P5"] as const)[index]!;
      assertStageTopology(index);
      return Object.freeze({ stage, state: "pre-status", publicationSet, rawFence, topology: Object.freeze([prefixDepth, phaseTopologyMembers, prefixObservations, recordPrefixes.observations, p2Parent, operationMembers, controllerWriter, candidateWriters, publicationStates]) });
    }
    assertStageTopology(null);
    return Object.freeze({ phase: progressTopology.phase, stage: "P5", state: progressTopology.state, publicationSet, rawFence, topology: Object.freeze([prefixDepth, phaseTopologyMembers, prefixObservations, recordPrefixes.observations, p2Parent, operationMembers, controllerWriter, candidateWriters, publicationStates]) });
  } finally { originals.close(); }
}

function assertExactPoisonPostVisiblePreStatusEqualV1(
  left: ExactPoisonPostVisiblePreStatusPassV1,
  right: ExactPoisonPostVisiblePreStatusPassV1,
): void {
  const comparable = (pass: ExactPoisonPostVisiblePreStatusPassV1) => ({
    stage: pass.stage,
    state: pass.state,
    rawFence: pass.rawFence,
    topology: pass.topology,
    operationDirectoryPrefix: pass.publicationSet.operationDirectoryPrefix,
    controllerLockTarget: pass.publicationSet.controllerLockTarget,
    candidates: pass.publicationSet.candidates.map((candidate) => ({ phase: candidate.phase, target: candidate.target, bytesSha256: sha256(candidate.bytes), byteLength: candidate.bytes.length })),
  });
  if (canonicalComparable(comparable(left)) !== canonicalComparable(comparable(right))) currentEntryFail("post-visible pre-status A/B observation changed");
}

async function revalidatePostVisibleCurrentEntryStoreProgressV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
): Promise<ExactPoisonPostVisibleZeroProgressSelectionV1> {
  const rootIdentity = observeExactPoisonPostVisibleSuccessorRootIdentityV1(context);
  const passA = await observeExactPoisonPostVisibleProgressPassNoWriteV1(context);
  context.assertStable();
  context.successorRootParent.assertStable();
  assertExactPoisonPostVisibleSuccessorRootIdentityV1(context, rootIdentity);
  const passB = await observeExactPoisonPostVisibleProgressPassNoWriteV1(context);
  assertExactPoisonPostVisibleProgressPassEqualV1(passA, passB);
  context.assertStable();
  context.successorRootParent.assertStable();
  assertExactPoisonPostVisibleSuccessorRootIdentityV1(context, rootIdentity);
  if (passB.status.state === "blocked") {
    const selection = requireExactPoisonPostVisibleProgressRowV1(passB.status);
    if (selection.state !== "blocked" || !selection.lastValidRow || !selection.blockedReason) currentEntryFail("post-visible current-entry progress blocked evidence is invalid");
    currentEntryFail("post-visible current-entry progress is blocked");
  }
  return Object.freeze({ storeRoot: context.successorRoot, operation: Object.freeze({ operationRef: context.successorOperation.operationRef, operationHash: context.successorOperation.operationHash }), selectionKind: "successor-progress" });
}

async function revalidatePostVisibleCurrentEntryStoreV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
): Promise<ExactPoisonPostVisibleZeroProgressSelectionV1> {
  context.assertStable();
  context.successorRootParent.assertStable();
  const rootIdentity = exactPoisonPostVisibleSuccessorRootIdentityV1(context);
  const operations = path.join(context.successorRoot, "operations");
  let operationsPresent = false;
  try { lstatSync(operations, { bigint: true }); operationsPresent = true; }
  catch (error) { if (!isEnoent(error)) throw error; }
  if (operationsPresent) {
    const dispatch = classifyExactPoisonPostVisibleCurrentStatusDispatchV1(context);
    if (dispatch === "progress") return await revalidatePostVisibleCurrentEntryStoreProgressV1(context);
    const passA = await observeExactPoisonPostVisiblePreStatusPassNoWriteV1(context);
    context.assertStable();
    context.successorRootParent.assertStable();
    const passB = await observeExactPoisonPostVisiblePreStatusPassNoWriteV1(context);
    assertExactPoisonPostVisiblePreStatusEqualV1(passA, passB);
    if (passB.state === "progress") currentEntryFail("post-visible current-entry progress bypassed strict dispatch");
    context.assertStable();
    context.successorRootParent.assertStable();
    assertExactPoisonPostVisibleSuccessorRootIdentityV1(context, rootIdentity);
    return Object.freeze({
      storeRoot: context.successorRoot,
      operation: Object.freeze({ operationRef: context.successorOperation.operationRef, operationHash: context.successorOperation.operationHash }),
      selectionKind: "successor-pre-status",
    });
  }
  assertExactPoisonPostVisibleZeroProgressPrefixAbsentV1(context);
  context.assertStable();
  context.successorRootParent.assertStable();
  await observeExactPoisonRecoveryPostVisibleZeroFenceV1(context);
  context.assertStable();
  context.successorRootParent.assertStable();
  assertExactPoisonPostVisibleSuccessorRootIdentityV1(context, rootIdentity);
  assertExactPoisonPostVisibleZeroProgressPrefixAbsentV1(context);
  context.assertStable();
  context.successorRootParent.assertStable();
  assertExactPoisonPostVisibleSuccessorRootIdentityV1(context, rootIdentity);
  return Object.freeze({
    storeRoot: context.successorRoot,
    operation: Object.freeze({
      operationRef: context.successorOperation.operationRef,
      operationHash: context.successorOperation.operationHash
    }),
    selectionKind: "successor-zero-progress",
  });
}

type ExactPoisonPostVisibleZeroProgressSelectionV1 = Readonly<{
  storeRoot: string;
  operation: InternalProductionCurrentEntryOperationPairV1;
  selectionKind: "successor-zero-progress" | "successor-pre-status" | "successor-progress";
}>;

type ExactPoisonRecoveryPostVisibleOriginalsV1 = Readonly<{
  evidence: ExactPoisonRecoveryInventoryEvidenceV1;
  close: () => void;
}>;

function exactPoisonRecoveryPinnedRecordFileSnapshotV1(
  record: ExactPoisonRecoveryPinnedRecordV1,
): FileSnapshot {
  return Object.freeze({
    locator: record.target,
    observed: Object.freeze({
      bytes: record.bytes,
      mode: Number(record.identity.mode & 0o7777n),
      stats: record.identity,
    }),
  });
}

function openExactPoisonRecoveryPostVisibleOriginalsV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
): ExactPoisonRecoveryPostVisibleOriginalsV1 {
  const quarantinedInventory = context.dispositionValue.value.quarantinedInventory;
  const predecessorFileIdentities = context.zeroEffectProof.value.predecessorFileIdentities;
  if (
    !isPlainRecord(quarantinedInventory)
    || !hasExactKeys(quarantinedInventory, ["inventoryBody", "inventoryHash"])
    || !isPlainRecord(quarantinedInventory.inventoryBody)
    || quarantinedInventory.inventoryHash !== EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1
    || hashCanonicalJson(quarantinedInventory.inventoryBody) !== EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1
    || canonicalComparable(predecessorFileIdentities) !== canonicalComparable(EXACT_POISON_PREDECESSOR_FILE_IDENTITIES_V1)
  ) currentEntryFail("post-visible original inventory evidence is crossed");
  const inventoryBody = quarantinedInventory.inventoryBody;
  const orderedDirectories = inventoryBody.orderedDirectories;
  const orderedFiles = inventoryBody.orderedFiles;
  if (
    !Array.isArray(orderedDirectories)
    || orderedDirectories.length !== 10
    || !Array.isArray(orderedFiles)
    || orderedFiles.length !== 5
    || !Array.isArray(predecessorFileIdentities)
    || predecessorFileIdentities.length !== 5
  ) currentEntryFail("post-visible original inventory cardinality is crossed");

  const root = fixedLegacyCurrentEntryRootV1();
  const directoryPins: ExactPoisonRecoveryOwnedParentV1[] = [];
  const filePins: ExactPoisonRecoveryPinnedRecordV1[] = [];
  let closed = false;
  const close = (): void => {
    if (closed) return;
    closed = true;
    for (let index = filePins.length - 1; index >= 0; index -= 1) closeSync(filePins[index]!.descriptor);
    for (let index = directoryPins.length - 1; index >= 0; index -= 1) directoryPins[index]!.close();
  };
  try {
    EXACT_POISON_ORIGINAL_DIRECTORY_LOCATORS_V1.map((locator) => {
      const index = EXACT_POISON_ORIGINAL_DIRECTORY_LOCATORS_V1.indexOf(locator);
      const expected = orderedDirectories[index];
      if (!isPlainRecord(expected) || !hasExactKeys(expected, ["deviceDecimal", "inodeDecimal", "locator", "mode", "uidDecimal"])) {
        currentEntryFail(`post-visible original directory ${index} evidence is invalid`);
      }
      const target = locator === "." ? root : path.join(root, locator);
      const owned = openExactPoisonRecoveryPinnedParentV1(target);
      directoryPins.push(owned);
      const identity = owned.pin.identity;
      if (
        expected.locator !== locator
        || expected.deviceDecimal !== identity.dev.toString(10)
        || expected.inodeDecimal !== identity.ino.toString(10)
        || expected.mode !== `0${(identity.mode & 0o7777n).toString(8)}`
        || expected.uidDecimal !== identity.uid.toString(10)
      ) currentEntryFail(`post-visible original directory ${locator} is crossed`);
      return owned;
    });
    EXACT_POISON_ORIGINAL_FILE_LOCATORS_V1.map((locator) => {
      const index = EXACT_POISON_ORIGINAL_FILE_LOCATORS_V1.indexOf(locator);
      const expected = orderedFiles[index];
      const expectedIdentity = predecessorFileIdentities[index];
      if (
        !isPlainRecord(expected)
        || !hasExactKeys(expected, ["byteLength", "bytesSha256", "linkCount", "locator", "mode"])
        || !isPlainRecord(expectedIdentity)
        || !hasExactKeys(expectedIdentity, ["locator", "uidDecimal", "deviceDecimal", "inodeDecimal"])
      ) currentEntryFail(`post-visible original file ${index} evidence is invalid`);
      const record = openExactPoisonRecoveryPinnedRecordV1(path.join(root, locator), `post-visible original file ${locator}`);
      filePins.push(record);
      if (
        expected.locator !== locator
        || expected.byteLength !== record.bytes.length
        || expected.bytesSha256 !== sha256(record.bytes)
        || expected.linkCount !== Number(record.identity.nlink)
        || expected.mode !== `0${(record.identity.mode & 0o7777n).toString(8)}`
        || expectedIdentity.locator !== locator
        || expectedIdentity.uidDecimal !== record.identity.uid.toString(10)
        || expectedIdentity.deviceDecimal !== record.identity.dev.toString(10)
        || expectedIdentity.inodeDecimal !== record.identity.ino.toString(10)
      ) currentEntryFail(`post-visible original file ${locator} is crossed`);
      return record;
    });
    if (directoryPins.length !== 10 || filePins.length !== 5) currentEntryFail("post-visible original pin count is crossed");
    const assertStableOriginals = (): void => {
      if (closed) currentEntryFail("post-visible original pins are closed");
      context.assertStable();
      for (const directory of directoryPins) directory.pin.assertStable();
      for (const [index, record] of filePins.entries()) {
        assertExactPoisonRecoveryPinnedRecordStableV1(record, `post-visible original file ${index}`);
      }
      for (const directory of directoryPins) directory.pin.assertStable();
      context.assertStable();
    };
    assertStableOriginals();
    return Object.freeze({
      evidence: Object.freeze({
        inventoryBody,
        inventoryHash: EXACT_POISON_QUARANTINED_INVENTORY_HASH_V1,
        predecessorFileIdentities: EXACT_POISON_PREDECESSOR_FILE_IDENTITIES_V1,
        assertStableOriginals,
      }),
      close,
    });
  } catch (error) {
    close();
    throw error;
  }
}

type ExactPoisonPostVisibleSuccessorRootIdentityV1 = Readonly<{
  dev: bigint;
  ino: bigint;
  mode: bigint;
  uid: bigint;
  nlink: bigint;
  size: bigint;
  mtimeNs: bigint;
  ctimeNs: bigint;
}>;

function exactPoisonPostVisibleSuccessorRootIdentityV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
): ExactPoisonPostVisibleSuccessorRootIdentityV1 {
  context.successorRootParent.assertStable();
  const before = fstatSync(context.successorRootParent.descriptor, { bigint: true });
  const atPath = lstatSync(context.successorRoot, { bigint: true });
  if (
    !before.isDirectory()
    || !atPath.isDirectory()
    || atPath.isSymbolicLink()
    || !sameRegularMetadata(before, atPath)
    || (before.mode & 0o7777n) !== 0o700n
  ) currentEntryFail("post-visible successor root identity is crossed");
  context.successorRootParent.assertStable();
  const after = fstatSync(context.successorRootParent.descriptor, { bigint: true });
  const reopened = lstatSync(context.successorRoot, { bigint: true });
  if (
    !after.isDirectory()
    || !reopened.isDirectory()
    || reopened.isSymbolicLink()
    || !sameRegularMetadata(before, after)
    || !sameRegularMetadata(before, reopened)
  ) currentEntryFail("post-visible successor root identity moved while observed");
  return Object.freeze({
    dev: after.dev,
    ino: after.ino,
    mode: after.mode,
    uid: after.uid,
    nlink: after.nlink,
    size: after.size,
    mtimeNs: after.mtimeNs,
    ctimeNs: after.ctimeNs,
  });
}

function observeExactPoisonPostVisibleSuccessorRootIdentityV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
): ExactPoisonPostVisibleSuccessorRootIdentityV1 {
  return exactPoisonPostVisibleSuccessorRootIdentityV1(context);
}

function assertExactPoisonPostVisibleSuccessorRootIdentityV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
  expected: ExactPoisonPostVisibleSuccessorRootIdentityV1,
): void {
  const observed = exactPoisonPostVisibleSuccessorRootIdentityV1(context);
  if (
    observed.dev !== expected.dev
    || observed.ino !== expected.ino
    || observed.mode !== expected.mode
    || observed.uid !== expected.uid
    || observed.nlink !== expected.nlink
    || observed.size !== expected.size
    || observed.mtimeNs !== expected.mtimeNs
    || observed.ctimeNs !== expected.ctimeNs
  ) currentEntryFail("post-visible successor root metadata drifted");
}

function assertExactPoisonPostVisibleZeroProgressPrefixAbsentV1(
  context: ExactPoisonRecoveryPinnedCommitChainV1,
): void {
  const operationsPath = path.join(context.successorRoot, "operations");
  if (path.dirname(operationsPath) !== context.successorRoot || path.relative(context.successorRoot, operationsPath) !== "operations") {
    currentEntryFail("post-visible operations prefix escaped the successor root");
  }
  context.successorRootParent.assertStable();
  try {
    lstatSync(operationsPath, { bigint: true });
    currentEntryFail("post-visible operations prefix is visible");
  } catch (error) {
    if (!isEnoent(error)) throw error;
  }
  context.successorRootParent.assertStable();
  try {
    lstatSync(operationsPath, { bigint: true });
    currentEntryFail("post-visible operations prefix appeared while observed");
  } catch (error) {
    if (!isEnoent(error)) throw error;
  }
  context.successorRootParent.assertStable();
}

function assertExactPoisonRecoveryFrontierV1(
  candidates: ExactPoisonQuarantineAdmissionV1["candidates"],
  heldWriter: ExactPoisonRecoveryWriterV1,
): void {
  heldWriter.assertStable();
  const root = fixedLegacyCurrentEntryRootV1();
  const rootStats = lstatSync(root, { bigint: true });
  const directoriesByPhase = candidates.map(exactPoisonRecoveryCandidateDirectoriesV1);
  const allDirectories = new Set(directoriesByPhase.flat());
  const allowedDirectoryChildren = new Map<string, Set<string>>();
  const allowedFileChildren = new Map<string, Set<string>>();
  for (const directory of allDirectories) {
    const parent = path.dirname(directory);
    const members = allowedDirectoryChildren.get(parent) ?? new Set<string>();
    members.add(path.basename(directory));
    allowedDirectoryChildren.set(parent, members);
  }
  for (const candidate of candidates) {
    const directory = path.dirname(candidate.target);
    const members = allowedFileChildren.get(directory) ?? new Set<string>();
    members.add(path.basename(candidate.target));
    allowedFileChildren.set(directory, members);
  }
  const existingDirectories = new Set<string>();
  const orderedDirectories = [...allDirectories].sort((left, right) => {
    const depth = left.split(path.sep).length - right.split(path.sep).length;
    return depth === 0 ? compareBytes(left, right) : depth;
  });
  for (const directory of orderedDirectories) {
    let stats: BigIntStats;
    try { stats = lstatSync(directory, { bigint: true }); } catch (error) { if (isEnoent(error)) continue; throw error; }
    if (
      !stats.isDirectory()
      || stats.isSymbolicLink()
      || stats.dev !== rootStats.dev
      || stats.uid !== rootStats.uid
      || (stats.mode & 0o7777n) !== 0o700n
      || realpathSync(directory) !== directory
    ) currentEntryFail("exact-poison recovery frontier directory is invalid");
    existingDirectories.add(directory);
    const allowedDirectories = allowedDirectoryChildren.get(directory) ?? new Set<string>();
    const allowedFiles = allowedFileChildren.get(directory) ?? new Set<string>();
    for (const member of readdirSync(directory)) {
      if (allowedDirectories.has(member) || allowedFiles.has(member)) continue;
      const matchesTemp = candidates.some((candidate) => path.dirname(candidate.target) === directory && exactPoisonRecoveryTempPatternV1(candidate).test(member));
      if (!matchesTemp) currentEntryFail("exact-poison recovery frontier contains an unknown member");
    }
  }
  const states: Array<"absent" | "current" | "complete"> = [];
  for (const [index, candidate] of candidates.entries()) {
    const directory = path.dirname(candidate.target);
    const tempNames = existingDirectories.has(directory)
      ? readdirSync(directory).filter((entry) => exactPoisonRecoveryTempPatternV1(candidate).test(entry)).sort(compareBytes)
      : [];
    if (tempNames.length > 1) currentEntryFail("exact-poison recovery temp cap exceeded");
    const tempTarget = tempNames.length === 1 ? path.join(directory, tempNames[0]!) : null;
    let temp: ExactPoisonRecoveryPinnedMemberV1 | null = null;
    let final: ExactPoisonRecoveryPinnedMemberV1 | null = null;
    try {
      temp = tempTarget === null ? null : openExactPoisonRecoveryMemberV1(tempTarget, `exact-poison recovery temp ${index}`);
      final = exactPoisonRecoveryMemberIfPresentV1(candidate.target, `exact-poison recovery final ${index}`);
      if (final === null && temp === null) {
        states.push("absent");
      } else if (final === null && temp !== null && temp.identity.nlink === 1n) {
        states.push("current");
      } else if (final !== null && temp === null && final.identity.nlink === 1n && final.bytes.equals(candidate.bytes)) {
        states.push("complete");
      } else if (
        final !== null
        && temp !== null
        && final.bytes.equals(candidate.bytes)
        && temp.bytes.equals(candidate.bytes)
        && final.identity.nlink === 2n
        && temp.identity.nlink === 2n
        && final.identity.dev === temp.identity.dev
        && final.identity.ino === temp.identity.ino
      ) {
        states.push("current");
      } else {
        currentEntryFail(`exact-poison recovery phase ${index} physical state is invalid`);
      }
    } finally {
      if (temp !== null) closeSync(temp.descriptor);
      if (final !== null) closeSync(final.descriptor);
    }
  }
  const firstIncomplete = states.findIndex((state) => state !== "complete");
  const frontier = firstIncomplete < 0 ? candidates.length : firstIncomplete;
  if (states.slice(frontier + 1).some((state) => state !== "absent")) {
    currentEntryFail("exact-poison recovery phases are not an ordered prefix");
  }
  const requiredDirectories = new Set<string>();
  for (const phaseDirectories of directoriesByPhase.slice(0, frontier)) {
    for (const directory of phaseDirectories) requiredDirectories.add(directory);
  }
  const currentDirectories = frontier < candidates.length
    ? directoriesByPhase[frontier]!.filter((directory) => !requiredDirectories.has(directory))
    : [];
  const currentEndpointPresent = frontier < candidates.length && states[frontier] === "current";
  let observedPrefixLength = 0;
  while (observedPrefixLength < currentDirectories.length && existingDirectories.has(currentDirectories[observedPrefixLength]!)) {
    requiredDirectories.add(currentDirectories[observedPrefixLength]!);
    observedPrefixLength += 1;
  }
  if (
    (currentEndpointPresent && observedPrefixLength !== currentDirectories.length)
    || currentDirectories.slice(observedPrefixLength).some((directory) => existingDirectories.has(directory))
    || [...existingDirectories].some((directory) => !requiredDirectories.has(directory))
  ) currentEntryFail("exact-poison recovery directory frontier is not an ordered prefix");
  heldWriter.assertStable();
}

function ensureExactPoisonRecoveryCandidateDirectoryV1(
  candidate: ExactPoisonRecoveryCandidateV1,
  heldWriter: ExactPoisonRecoveryWriterV1,
): void {
  const root = fixedLegacyCurrentEntryRootV1();
  const rootStats = lstatSync(root, { bigint: true });
  for (const directory of exactPoisonRecoveryCandidateDirectoriesV1(candidate)) {
    heldWriter.assertStable();
    const parent = path.dirname(directory);
    const guard = authenticateTask12ReceiptDirectoryChainV1(parent);
    try {
      guard.assertStable();
      try { mkdirSync(directory, { mode: 0o700 }); } catch (error) { if (!isEexist(error)) throw error; }
      guard.assertStable();
      fsyncExactPoisonRecoveryCandidateParentV1(heldWriter, parent);
    } finally {
      guard.close();
    }
    const stats = lstatSync(directory, { bigint: true });
    if (
      !stats.isDirectory()
      || stats.isSymbolicLink()
      || stats.dev !== rootStats.dev
      || stats.uid !== rootStats.uid
      || (stats.mode & 0o7777n) !== 0o700n
      || realpathSync(directory) !== directory
    ) currentEntryFail("exact-poison recovery candidate directory is invalid");
    heldWriter.assertStable();
  }
}

function fsyncExactPoisonRecoveryCandidateParentV1(
  heldWriter: ExactPoisonRecoveryWriterV1,
  directory: string,
): void {
  const guard = authenticateTask12ReceiptDirectoryChainV1(directory);
  let descriptor = -1;
  try {
    heldWriter.assertStable();
    guard.assertStable();
    descriptor = openSync(directory, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_DIRECTORY);
    const before = fstatSync(descriptor, { bigint: true });
    const atPath = lstatSync(directory, { bigint: true });
    if (!before.isDirectory() || !sameRegularMetadata(before, atPath)) {
      // Directory timestamps/link counts may change, but the opened identity,
      // ownership, mode, and device must remain the authenticated member.
      if (
        !atPath.isDirectory()
        || atPath.isSymbolicLink()
        || before.dev !== atPath.dev
        || before.ino !== atPath.ino
        || before.mode !== atPath.mode
        || before.uid !== atPath.uid
      ) currentEntryFail("exact-poison recovery parent identity is invalid");
    }
    fsyncSync(descriptor);
    const after = fstatSync(descriptor, { bigint: true });
    const reopened = lstatSync(directory, { bigint: true });
    if (
      !after.isDirectory()
      || !reopened.isDirectory()
      || reopened.isSymbolicLink()
      || after.dev !== before.dev
      || after.ino !== before.ino
      || after.mode !== before.mode
      || after.uid !== before.uid
      || reopened.dev !== before.dev
      || reopened.ino !== before.ino
      || reopened.mode !== before.mode
      || reopened.uid !== before.uid
    ) currentEntryFail("exact-poison recovery parent changed while fsynced");
    guard.assertStable();
    heldWriter.assertStable();
  } finally {
    if (descriptor >= 0) closeSync(descriptor);
    guard.close();
  }
}

function isEexist(error: unknown): boolean {
  return error instanceof Error && "code" in error && error.code === "EEXIST";
}

function isExactPoisonRecoveryCurrentFamilyBytesV1(
  bytes: Buffer,
  candidate: ExactPoisonRecoveryCandidateV1,
  phase: ExactPoisonRecoveryPublicationPhaseV1,
): boolean {
  try {
    const value = strictCanonicalRecord(bytes, `exact-poison ${phase} recovery temp`);
    const admitted = strictCanonicalRecord(candidate.bytes, `exact-poison admitted ${phase}`);
    if (canonicalComparable(Object.keys(value).sort(compareBytes)) !== canonicalComparable(Object.keys(admitted).sort(compareBytes))) return false;
    if (value.schema !== admitted.schema) return false;
    const shape = {
      disposition: ["dispositionRef", "dispositionHash"],
      "successor-authority-v31": ["authorityV3Migration31AuditRef", "authorityV3Migration31AuditHash"],
      "successor-pending": ["pendingBootstrapHandoffMigrationRef", "pendingBootstrapHandoffMigrationHash"],
      "successor-operation": ["operationRef", "operationHash"],
      "successor-edge": ["edgeRef", "edgeHash"],
      "successor-activation-seal": ["activationSealRef", "activationSealHash"],
      "successor-activation-commit": ["activationCommitRef", "activationCommitHash"],
    } as const;
    const [refKey, hashKey] = shape[phase];
    const hash = value[hashKey];
    const admittedRef = admitted[refKey];
    if (typeof hash !== "string" || !SHA256.test(hash) || typeof admittedRef !== "string") return false;
    const suffix = admittedRef.slice(0, -64);
    if (value[refKey] !== `${suffix}${hash}`) return false;
    const core = { ...value };
    delete core[refKey];
    delete core[hashKey];
    return hashCanonicalJson(core) === hash;
  } catch {
    return false;
  }
}

async function assertExactPoisonRecoveryPublicationFenceV1(
  operation: FileSnapshot,
  admitted: ExactPoisonQuarantineAdmissionV1,
  heldWriter: ExactPoisonRecoveryWriterV1,
): Promise<void> {
  const observed = await observeExactPoisonQuarantineAdmissionV1(operation, heldWriter);
  assertExactPoisonQuarantineAdmissionCandidatesEqualV1(observed.candidates, admitted.candidates);
  heldWriter.assertStable();
  observed.assertStableOriginals();
}

function exactPoisonRecoveryPublicationFaultV1(
  _phase: ExactPoisonRecoveryPublicationPhaseV1,
  _ordinal: 0 | 1 | 2 | 3 | 4 | 5 | 6,
  _boundary: "temp-create" | "complete-write" | "fchmod" | "file-fsync" | "close" | "link" | "parent-fsync" | "incomplete-unlink" | "selected-unlink" | "final-reopen",
): void {
  // A deliberately inert, module-private seam. Copied-module crash tests replace
  // only literal call sites; production has no environment or global switch.
}

async function publishExactPoisonRecoveryCandidateV1(
  operation: FileSnapshot,
  admitted: ExactPoisonQuarantineAdmissionV1,
  phase: ExactPoisonRecoveryPublicationPhaseV1,
  ordinal: 0 | 1 | 2 | 3 | 4 | 5 | 6,
  heldWriter: ExactPoisonRecoveryWriterV1,
): Promise<void> {
  const candidate = admitted.candidates[ordinal];
  if (EXACT_POISON_RECOVERY_PUBLICATION_PHASES_V1[ordinal]?.phase !== phase) {
    currentEntryFail("exact-poison recovery publication phase is crossed");
  }
  await assertExactPoisonRecoveryPublicationFenceV1(operation, admitted, heldWriter);
  ensureExactPoisonRecoveryCandidateDirectoryV1(candidate, heldWriter);
  await assertExactPoisonRecoveryPublicationFenceV1(operation, admitted, heldWriter);
  const directory = path.dirname(candidate.target);
  const basename = path.basename(candidate.target);
  const pattern = exactPoisonRecoveryTempPatternV1(candidate);
  for (;;) {
    heldWriter.assertStable();
    const members = readdirSync(directory).sort(compareBytes);
    const names = members.filter((entry) => pattern.test(entry));
    if (names.length > 1) currentEntryFail("exact-poison recovery temp cap exceeded");
    const temp = names.length === 1
      ? path.join(directory, names[0]!)
      : path.join(directory, `.${basename}.00000000-0000-4000-8000-000000000001.tmp`);
    let existingTemp: ExactPoisonRecoveryPinnedMemberV1 | null = null;
    let existingFinal: ExactPoisonRecoveryPinnedMemberV1 | null = null;
    let tempDescriptor = -1;
    let selected: ExactPoisonRecoveryPinnedMemberV1 | null = null;
    let selectedOwned = false;
    try {
      existingTemp = names.length === 1
        ? openExactPoisonRecoveryMemberV1(temp, `exact-poison ${phase} temp`)
        : null;
      existingFinal = exactPoisonRecoveryMemberIfPresentV1(candidate.target, `exact-poison ${phase} final`);
      if (existingFinal !== null && existingTemp === null) {
        if (existingFinal.identity.nlink !== 1n || !existingFinal.bytes.equals(candidate.bytes)) {
          currentEntryFail(`exact-poison ${phase} final is crossed`);
        }
      } else if (existingFinal !== null && existingTemp !== null) {
        if (
          existingFinal.identity.nlink !== 2n
          || existingTemp.identity.nlink !== 2n
          || existingFinal.identity.dev !== existingTemp.identity.dev
          || existingFinal.identity.ino !== existingTemp.identity.ino
          || !existingFinal.bytes.equals(candidate.bytes)
          || !existingTemp.bytes.equals(candidate.bytes)
        ) currentEntryFail(`exact-poison ${phase} selected temp is crossed`);
        selected = existingTemp;
      } else if (existingFinal === null && existingTemp !== null && !existingTemp.bytes.equals(candidate.bytes)) {
        if (isExactPoisonRecoveryCurrentFamilyBytesV1(existingTemp.bytes, candidate, phase)) {
          currentEntryFail(`exact-poison ${phase} has competing current-family bytes`);
        }
        await assertExactPoisonRecoveryPublicationFenceV1(operation, admitted, heldWriter);
        assertExactPoisonRecoveryPinnedMemberStableV1(temp, existingTemp, `exact-poison ${phase} incomplete temp`);
        unlinkSync(temp);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "incomplete-unlink");
        fsyncExactPoisonRecoveryCandidateParentV1(heldWriter, directory);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "parent-fsync");
        continue;
      } else if (existingFinal === null && existingTemp === null) {
        tempDescriptor = openSync(temp, constants.O_CREAT | constants.O_EXCL | constants.O_RDWR | constants.O_NOFOLLOW, 0o600);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "temp-create");
        writeFileSync(tempDescriptor, candidate.bytes);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "complete-write");
        fchmodSync(tempDescriptor, 0o600);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "fchmod");
        fsyncSync(tempDescriptor);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "file-fsync");
    closeSync(tempDescriptor);
    tempDescriptor = -1;
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "close");
        selected = openExactPoisonRecoveryMemberV1(temp, `exact-poison ${phase} link candidate`);
        selectedOwned = true;
      } else if (existingFinal === null && existingTemp !== null) {
        if (existingTemp.identity.nlink !== 1n || !existingTemp.bytes.equals(candidate.bytes)) {
          currentEntryFail(`exact-poison ${phase} temp is crossed`);
        }
        fsyncSync(existingTemp.descriptor);
        selected = existingTemp;
      }

      if (existingFinal === null) {
        if (selected === null) currentEntryFail(`exact-poison ${phase} link candidate is absent`);
        if (selected.identity.nlink !== 1n || !selected.bytes.equals(candidate.bytes)) {
          currentEntryFail(`exact-poison ${phase} link candidate is crossed`);
        }
        await assertExactPoisonRecoveryPublicationFenceV1(operation, admitted, heldWriter);
        assertExactPoisonRecoveryPinnedMemberStableV1(temp, selected, `exact-poison ${phase} link candidate`);
        linkSync(temp, candidate.target);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "link");
        fsyncExactPoisonRecoveryCandidateParentV1(heldWriter, directory);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "parent-fsync");
        const linkedTemp = fstatSync(selected.descriptor, { bigint: true });
        const linkedFinal = lstatSync(candidate.target, { bigint: true });
        if (
          linkedTemp.nlink !== 2n
          || linkedFinal.nlink !== 2n
          || linkedTemp.dev !== selected.identity.dev
          || linkedTemp.ino !== selected.identity.ino
          || linkedFinal.dev !== selected.identity.dev
          || linkedFinal.ino !== selected.identity.ino
        ) currentEntryFail(`exact-poison ${phase} link proof failed`);
        const refreshedSelected = openExactPoisonRecoveryMemberV1(temp, `exact-poison ${phase} selected link`);
        if (selectedOwned) closeSync(selected.descriptor);
        selected = refreshedSelected;
        selectedOwned = true;
      }

      fsyncExactPoisonRecoveryCandidateParentV1(heldWriter, directory);
      exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "parent-fsync");
      await assertExactPoisonRecoveryPublicationFenceV1(operation, admitted, heldWriter);
      if (selected !== null) {
        assertExactPoisonRecoveryPinnedMemberStableV1(temp, selected, `exact-poison ${phase} selected temp`);
        const selectedFinal = lstatSync(candidate.target, { bigint: true });
        const selectedNow = fstatSync(selected.descriptor, { bigint: true });
        if (
          selectedFinal.dev !== selectedNow.dev
          || selectedFinal.ino !== selectedNow.ino
          || selectedFinal.nlink !== 2n
          || selectedNow.nlink !== 2n
        ) currentEntryFail(`exact-poison ${phase} selected final changed before cleanup`);
        await assertExactPoisonRecoveryPublicationFenceV1(operation, admitted, heldWriter);
        unlinkSync(temp);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "selected-unlink");
        fsyncExactPoisonRecoveryCandidateParentV1(heldWriter, directory);
        exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "parent-fsync");
      }
      const reopened = readTask12ReceiptStoreSnapshotV1(candidate.target);
      if (!reopened.bytes.equals(candidate.bytes)) currentEntryFail(`exact-poison ${phase} final did not reopen`);
      exactPoisonRecoveryPublicationFaultV1(phase, ordinal, "final-reopen");
      await assertExactPoisonRecoveryPublicationFenceV1(operation, admitted, heldWriter);
      return;
    } finally {
      if (tempDescriptor >= 0) closeSync(tempDescriptor);
      if (selectedOwned && selected !== null) closeSync(selected.descriptor);
      if (existingTemp !== null) closeSync(existingTemp.descriptor);
      if (existingFinal !== null) closeSync(existingFinal.descriptor);
    }
  }
}

async function resumeExactPoisonQuarantinePublisherCoreV1(): Promise<void> {
  const operation = requireExactPoisonRecoverySnapshotV1(
    fixedLegacyCurrentEntryOperationPathV1(),
    "fixed legacy exact-poison publisher operation",
  );
  const predecessorPair = parsePreselectionCurrentEntryOperationV1(operation.observed.bytes);
  if (
    predecessorPair.operationRef !== EXACT_POISON_OPERATION_REF_V1
    || predecessorPair.operationHash !== EXACT_POISON_OPERATION_HASH_V1
    || sha256(operation.observed.bytes) !== EXACT_POISON_OPERATION_BYTES_SHA256_V1
  ) currentEntryFail("fixed legacy exact-poison publisher operation is crossed");
  const heldWriter = acquireExactPoisonRecoveryWriterV1();
  try {
    heldWriter.assertStable();
    const admission = await observeExactPoisonQuarantineAdmissionV1(operation, heldWriter);
    for (const { phase, ordinal } of EXACT_POISON_RECOVERY_PUBLICATION_PHASES_V1) {
      await publishExactPoisonRecoveryCandidateV1(operation, admission, phase, ordinal, heldWriter);
      if (ordinal === 5) {
        const context = await openExactPoisonRecoveryPinnedSealChainV1();
        try { await durablyAuthenticateSuccessorActivationSealV1(context, heldWriter); }
        finally { context.close(); }
      }
      if (ordinal === 6) {
        const context = await openExactPoisonRecoveryPinnedCommitChainV1();
        try {
          heldWriter.assertStable();
          context.assertStable();
          await durablyAuthenticateSuccessorActivationCommitV1(context);
          heldWriter.assertStable();
          context.assertStable();
          await revalidatePostVisibleCurrentEntryStoreV1(context);
          heldWriter.assertStable();
          context.assertStable();
        } finally { context.close(); }
      }
    }
    heldWriter.assertStable();
  } finally {
    heldWriter.close();
  }
}

async function resumeExactPoisonQuarantineBeforeSelectionV1(): Promise<void> {
  const operation = readFixedLegacyCurrentEntryRecordSnapshotIfPresentV1(
    fixedLegacyCurrentEntryOperationPathV1(),
    "fixed legacy current-entry operation",
  );
  if (operation === null) return;
  const pair = parsePreselectionCurrentEntryOperationV1(operation.observed.bytes);
  if (pair.operationHash !== EXACT_POISON_OPERATION_HASH_V1) return;
  if (
    pair.operationRef !== EXACT_POISON_OPERATION_REF_V1
    || sha256(operation.observed.bytes) !== EXACT_POISON_OPERATION_BYTES_SHA256_V1
  ) currentEntryFail("fixed legacy exact-poison operation bytes are crossed");
  const chain = await inspectExactPoisonRecoveryChainBeforeSelectionV1(operation);
  if (chain.state === "dispatch") {
    await resumeExactPoisonQuarantinePublisherCoreV1();
  } else {
    chain.context.close();
  }
}

function prepareCurrentEntryOperationPathV1(context: SelectedCurrentEntryStoreContextV1): string {
  const state = requireSelectedCurrentEntryStoreContextStateV1(context);
  return path.join(state.storeRoot, CURRENT_ENTRY_FILES.operation);
}

export async function prepareInternalProductionCurrentEntryOperationV1(): Promise<InternalProductionCurrentEntryOperationV1> {
  await resumeExactPoisonQuarantineBeforeSelectionV1();
  const context = await selectCurrentEntryStoreContextV1();
  const operationPath = prepareCurrentEntryOperationPathV1(context);
  const existingBytes = readCurrentEntryAuthorityRecordIfPresentV1(context, operationPath);
  if (existingBytes !== null) {
    const existing = strictCanonicalRecord(existingBytes, "current-entry operation");
    const existingPair = Object.freeze({ operationRef: existing.operationRef, operationHash: existing.operationHash });
    const resolved = await resolveInternalProductionCurrentEntryOperationWithSelectedCurrentEntryStoreContextV1(context,
      requirePair(existingPair, "operationRef", "operationHash", "setfarm://internal-production/current-entry-operation/sha256/") as InternalProductionCurrentEntryOperationPairV1,
    );
    const controllerLock = await acquireTask12ControllerLockV1(context, resolved.operationHash);
    try { return await ensureTask12PreparedCurrentEntryStatusV1(context, resolved); }
    finally { releaseTask12ControllerLockV1(controllerLock); }
  }
  const s0 = observeCurrentInternalProductionCleanSetfarmSourceBuildV1();
  const pba0 = await observeCurrentPba();
  const v31 = await observeCurrentInternalProductionAuthorityV3Migration31AuditWithSelectedCurrentEntryStoreContextV1(context);
  const pending = await observeCurrentInternalProductionPendingBootstrapHandoffMigrationWithSelectedCurrentEntryStoreContextV1(context);
  const s1 = observeCurrentInternalProductionCleanSetfarmSourceBuildV1();
  const pba1 = await observeCurrentPba();
  const v31Again = await observeCurrentInternalProductionAuthorityV3Migration31AuditWithSelectedCurrentEntryStoreContextV1(context);
  const pendingAgain = await observeCurrentInternalProductionPendingBootstrapHandoffMigrationWithSelectedCurrentEntryStoreContextV1(context);
  if (
    canonicalComparable(s0) !== canonicalComparable(s1)
    || canonicalComparable(pba0) !== canonicalComparable(pba1)
    || canonicalComparable(v31) !== canonicalComparable(v31Again)
    || canonicalComparable(pending) !== canonicalComparable(pendingAgain)
    || canonicalComparable(v31.controllerSource) !== canonicalComparable(s0)
    || canonicalComparable(pending.controllerSource) !== canonicalComparable(s0)
  ) currentEntryFail("current-entry prerequisites changed before publication");
  const body = {
    schema: "setfarm.internal-production-current-entry-operation.v1" as const,
    purpose: "task6a-internal-production-current-entry-v1" as const,
    controllerSource: s0,
    productBuildAuthorityV2DeliveryEvidence: pbaPair(pba0),
    productBuildAuthorityV2Observation: pba0,
    authorityV3Migration31Audit: v31Pair(v31),
    pendingBootstrapHandoffMigration: pendingPair(pending),
  };
  const operationHash = hashCanonicalJson(body);
  const value: InternalProductionCurrentEntryOperationV1 = Object.freeze({ ...body, operationRef: `setfarm://internal-production/current-entry-operation/sha256/${operationHash}`, operationHash });
  await publishCurrentEntryRecord(context, CURRENT_ENTRY_FILES.operation, await canonicalRecordBytes(value));
  const resolved = await resolveInternalProductionCurrentEntryOperationWithSelectedCurrentEntryStoreContextV1(context, operationPair(value));
  const finalV31 = await observeCurrentInternalProductionAuthorityV3Migration31AuditWithSelectedCurrentEntryStoreContextV1(context);
  const finalPending = await observeCurrentInternalProductionPendingBootstrapHandoffMigrationWithSelectedCurrentEntryStoreContextV1(context);
  const finalSource = observeCurrentInternalProductionCleanSetfarmSourceBuildV1();
  const finalPba = await observeCurrentPba();
  if (canonicalComparable(finalSource) !== canonicalComparable(s0) || canonicalComparable(finalPba) !== canonicalComparable(pba0) || canonicalComparable(v31Pair(finalV31)) !== canonicalComparable(v31Pair(v31)) || canonicalComparable(pendingPair(finalPending)) !== canonicalComparable(pendingPair(pending))) currentEntryFail("current-entry final equality fence failed");
  const controllerLock = await acquireTask12ControllerLockV1(context, resolved.operationHash);
  try { return await ensureTask12PreparedCurrentEntryStatusV1(context, resolved); }
  finally { releaseTask12ControllerLockV1(controllerLock); }
}

export async function resolveInternalProductionCurrentEntryOperationV1(
  pair: InternalProductionCurrentEntryOperationPairV1,
): Promise<InternalProductionCurrentEntryOperationV1> {
  const expected = requirePair(pair, "operationRef", "operationHash", "setfarm://internal-production/current-entry-operation/sha256/");
  const store = readFixedLegacyCurrentEntryStoreIfPresentV1();
  if (store === null) currentEntryFail("fixed legacy current-entry store is absent");
  const rootReader = openFixedLegacyCurrentEntryPrerequisiteRootReaderV1(store);
  try {
    rootReader.assertStable();
    const target = Object.freeze({ ...rootReader.store, basename: CURRENT_ENTRY_FILES.operation });
    const bytes = readCurrentEntryRecord(target.directory, target.basename, target.device);
    rootReader.assertStable();
    const body = strictCanonicalRecord(bytes, "current-entry operation");
    const fixedOperation = parsePreselectionCurrentEntryOperationV1(bytes);
    if (
      expected.operationRef === fixedOperation.operationRef
      && expected.operationHash === fixedOperation.operationHash
    )
      return await parseCurrentEntryOperationBodyCoreV1(
        body,
        expected,
        (nested, retained) => resolveInternalProductionAuthorityV3Migration31AuditAtFixedLegacyRootV1(nested, rootReader, retained),
        (nested, retained) => resolveInternalProductionPendingBootstrapHandoffMigrationAtFixedLegacyRootV1(nested, rootReader, retained),
      );
  } finally {
    rootReader.close();
  }
  const context = await openExactPoisonRecoveryPinnedCommitChainV1();
  try {
    if (
      expected.operationRef !== context.successorOperationPair.ref
      || expected.operationHash !== context.successorOperationPair.hash
      || expected.operationRef !== context.successorOperation.operationRef
      || expected.operationHash !== context.successorOperation.operationHash
    ) currentEntryFail("historical current-entry operation pair is unknown");
    context.assertStable();
    await durablyAuthenticateSuccessorActivationCommitV1(context);
    context.assertStable();
    return context.successorOperation;
  } finally {
    context.close();
  }
}

async function resolveInternalProductionCurrentEntryOperationWithSelectedCurrentEntryStoreContextV1(
  context: SelectedCurrentEntryStoreContextV1,
  pair: InternalProductionCurrentEntryOperationPairV1,
): Promise<InternalProductionCurrentEntryOperationV1> {
  const expected = requirePair(pair, "operationRef", "operationHash", "setfarm://internal-production/current-entry-operation/sha256/");
  const rootReader = openSelectedCurrentEntryPrerequisiteRootReaderV1(context);
  try {
    rootReader.assertStable();
    const target = fixedCurrentEntryPath(context, "operation");
    rootReader.assertStable();
    const body = strictCanonicalRecord(readCurrentEntryRecord(target.directory, target.basename, target.device), "current-entry operation");
    rootReader.assertStable();
    return await parseCurrentEntryOperationBodyWithSelectedCurrentEntryStoreContextV1(context, body, expected, rootReader);
  } finally {
    rootReader.close();
  }
}

async function parseCurrentEntryOperationBodyWithSelectedCurrentEntryStoreContextV1(
  context: SelectedCurrentEntryStoreContextV1,
  body: Record<string, unknown>,
  expected: Readonly<Record<string, string>>,
  rootReader?: CurrentEntryPrerequisiteRootReaderV1,
  retainedPrerequisites?: CurrentEntryPrerequisiteSnapshotV1[],
): Promise<InternalProductionCurrentEntryOperationV1> {
  const ownsRootReader = rootReader === undefined;
  rootReader ??= openSelectedCurrentEntryPrerequisiteRootReaderV1(context);
  try {
    rootReader.assertStable();
    const parsed = await parseCurrentEntryOperationBodyCoreV1(
      body,
      expected,
      (nested, retained) => resolveInternalProductionAuthorityV3Migration31AuditWithSelectedCurrentEntryStoreContextV1(context, nested, rootReader, retained),
      (nested, retained) => resolveInternalProductionPendingBootstrapHandoffMigrationWithSelectedCurrentEntryStoreContextV1(context, nested, rootReader, retained),
      retainedPrerequisites,
    );
    rootReader.assertStable();
    return parsed;
  } finally {
    if (ownsRootReader) rootReader.close();
  }
}

async function parseCurrentEntryOperationBodyCoreV1(
  body: Record<string, unknown>,
  expected: Readonly<Record<string, string>>,
  resolveV31: (pair: InternalProductionAuthorityV3Migration31AuditPairV1, retained?: CurrentEntryPrerequisiteSnapshotV1[]) => Promise<InternalProductionAuthorityV3Migration31AuditV1>,
  resolvePending: (pair: InternalProductionPendingBootstrapHandoffMigrationProjectionPairV1, retained?: CurrentEntryPrerequisiteSnapshotV1[]) => Promise<InternalProductionPendingBootstrapHandoffMigrationProjectionV1>,
  retainedPrerequisites?: CurrentEntryPrerequisiteSnapshotV1[],
): Promise<InternalProductionCurrentEntryOperationV1> {
  if (!hasExactKeys(body, ["schema", "purpose", "controllerSource", "productBuildAuthorityV2DeliveryEvidence", "productBuildAuthorityV2Observation", "authorityV3Migration31Audit", "pendingBootstrapHandoffMigration", "operationRef", "operationHash"])) currentEntryFail("current-entry operation fields are invalid");
  if (body.schema !== "setfarm.internal-production-current-entry-operation.v1" || body.purpose !== "task6a-internal-production-current-entry-v1") currentEntryFail("current-entry operation discriminator is invalid");
  const projection = { ...body };
  delete projection.operationRef;
  delete projection.operationHash;
  const hash = requireSha256(body.operationHash, "current-entry operation hash");
  if (hashCanonicalJson(projection) !== hash || body.operationRef !== `setfarm://internal-production/current-entry-operation/sha256/${hash}` || expected.operationHash !== hash || expected.operationRef !== body.operationRef) currentEntryFail("current-entry operation pair/hash is invalid");
  const source = requireSource(body.controllerSource);
  const v31 = await resolveV31(body.authorityV3Migration31Audit as InternalProductionAuthorityV3Migration31AuditPairV1, retainedPrerequisites);
  const pending = await resolvePending(body.pendingBootstrapHandoffMigration as InternalProductionPendingBootstrapHandoffMigrationProjectionPairV1, retainedPrerequisites);
  if (canonicalComparable(v31.controllerSource) !== canonicalComparable(source) || canonicalComparable(pending.controllerSource) !== canonicalComparable(source)) currentEntryFail("current-entry nested source is crossed");
  if (!isPlainRecord(body.productBuildAuthorityV2Observation) || !hasExactKeys(body.productBuildAuthorityV2Observation, ["schema", "observationTransport", "response"]) || body.productBuildAuthorityV2Observation.schema !== "setfarm.product-build-authority-v2-delivery-evidence-observation.v1" || body.productBuildAuthorityV2Observation.observationTransport !== "source-cli") currentEntryFail("stored PBA observation is invalid");
  const parsed = parseProductBuildAuthorityV2DeliveryEvidenceResponseV1(body.productBuildAuthorityV2Observation.response);
  const parsedPair = pbaPair(Object.freeze({ schema: "setfarm.product-build-authority-v2-delivery-evidence-observation.v1", observationTransport: "source-cli", response: parsed }) as ProductBuildAuthorityObservationV1);
  if (!isPlainRecord(body.productBuildAuthorityV2DeliveryEvidence) || !hasExactKeys(body.productBuildAuthorityV2DeliveryEvidence, ["deliveryEvidenceRef", "deliveryEvidenceHash"]) || body.productBuildAuthorityV2DeliveryEvidence.deliveryEvidenceRef !== parsedPair.deliveryEvidenceRef || body.productBuildAuthorityV2DeliveryEvidence.deliveryEvidenceHash !== parsedPair.deliveryEvidenceHash || canonicalComparable(body.productBuildAuthorityV2Observation.response) !== canonicalComparable(parsed)) currentEntryFail("stored PBA pair/response is crossed");
  return recursivelyFreeze(body as unknown as InternalProductionCurrentEntryOperationV1);
}

