      !identity.isFile()
      || identity.isSymbolicLink()
      || (identity.mode & 0o7777n) !== 0o600n
      || identity.nlink !== 1n
      || identity.dev !== parentIdentity.dev
      || identity.uid !== parentIdentity.uid
      || !sameRegularMetadata(identity, atPath)
      || identity.size < 0n
      || identity.size > BigInt(CURRENT_ENTRY_MAX_BYTES)
